// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 startBlock) public {
        vm.assume(actor != address(0) && actor != address(c));
        startBlock = bound(startBlock, 1, type(uint64).max);

        // Move to a fuzzed block so the target block (block.number + 1) is fuzzed too.
        vm.roll(startBlock);

        // The answer checked by settle() is keccak256(abi.encodePacked(blockhash(target)));
        // blockhash of a future/nonexistent block is deterministically bytes32(0).
        bytes32 winningGuess = keccak256(abi.encodePacked(bytes32(0)));

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(winningGuess);

        // Past the target block so settle() is admissible.
        vm.roll(startBlock + 2);
        vm.prank(actor);
        c.settle();

        // General rule: a settled winning guess always pays out 2 ether,
        // draining the contract (which started with 1 ether and took 1 more).
        assertTrue(address(c).balance == 0, "winning guess must be paid out");
    }
}

