pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 b) public {
        vm.assume(actor != address(0));
        b = bound(b, 1, type(uint256).max - 3);

        // actor locks in a guess at block b; target block is b+1
        vm.roll(b);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess(bytes32(0)); // hash value irrelevant for setup; any hash is stored

        // move past the target block and compute the real answer the contract will compute
        vm.roll(b + 2);
        bytes32 answer = keccak256(abi.encodePacked(blockhash(b + 1)));

        // actor re-locks? No: block != 0 blocks re-lock. Instead the winning hash must have
        // been the one locked in; so lock it properly from the start.
        // (Redo from a fresh state is impossible, so lock the winning hash first.)
        // The lock above stores whatever hash; for the payout rule to hold for ALL inputs,
        // we assert the balance invariant only when the stored guess wins. Hence lock the
        // winning hash as the fuzzed scenario: redo setup with correct hash.
        // --- corrected setup ---
        vm.roll(b);
        // settle previous (it never wins with bytes32(0) since answer is keccak256 != 0),
        // clearing the slot
        vm.prank(actor);
        c.settle();
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(answer);

        vm.roll(b + 2);
        vm.prank(actor);
        c.settle();

        // Reference: winning guess is paid out, draining c to 0. Mutant never stores the
        // hash (guess stays 0), never wins, so c keeps its 2 ether.
        assertTrue(address(c).balance == 0, "winning guess must be paid out");
    }
}

