pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 offset) public {
        // keep the domain wide but admissible
        vm.assume(actor != address(0) && actor != address(c) && actor.code.length == 0);
        offset = bound(offset, 1, 1000);

        uint256 lockBlock = block.number;
        uint256 targetBlock = lockBlock + offset;

        // In foundry, blockhash of any block not yet mined returns bytes32(0),
        // so settle() will compute answer = keccak256(abi.encodePacked(bytes32(0))).
        bytes32 h = keccak256(abi.encodePacked(bytes32(0)));

        vm.deal(actor, 2 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);

        vm.roll(targetBlock);
        vm.prank(actor);
        c.settle();

        // General rule: after locking the correct answer, settling pays the
        // actor 2 ether. The mutant never stores h, so the payout never occurs.
        assertTrue(address(actor).balance == 2 ether);
    }
}

