import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(address actor, uint256 extra) public {
        vm.assume(actor != address(c) && actor != address(this));
        extra = bound(extra, 0, 1000);

        // The target block's blockhash is guaranteed to be 0 once we roll
        // more than 256 blocks past it, so the settled answer is deterministic.
        bytes32 h = keccak256(abi.encodePacked(bytes32(0)));

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);

        uint256 target = block.number; // guesses[actor].block == target
        // Roll far past the 256-block hash window so blockhash(target) == 0
        vm.roll(target + 257 + extra);

        vm.prank(actor);
        c.settle();

        assertTrue(address(c).balance == 0);
    }
}

