contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 skipBlocks) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        bound(skipBlocks, 257, 100000);

        // A far-future blockhash is 0, so the winning guess is keccak256(0x00...00)
        bytes32 winningGuess = keccak256(abi.encodePacked(bytes32(0)));

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(winningGuess);

