pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(uint256 startBlock, address actor, bytes32 guess) public {
        // Admissible domain: a sane block height, a usable actor, and a winning guess.
        // (The target block's hash is 0 because we roll 300 blocks past it, so the
        // winning preimage is bytes32(0); we keep the guess as a fuzz parameter and
        // restrict the domain to the winning preimage.)
        startBlock = bound(startBlock, 1, 1e9);
        vm.assume(actor != address(0));
        bytes32 answer = keccak256(abi.encodePacked(bytes32(0)));
        vm.assume(guess == answer);

        vm.roll(startBlock);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // Roll far beyond the 256-block hash window so blockhash(target) == 0
        // and the stored guess is the winning answer.
        vm.roll(startBlock + 300);

        bool ok;
        vm.prank(actor);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: whenever settle() succeeds for a winning guess,
        // the full 2-ether pot is paid out and the contract balance is drained to 0.
        assertTrue(!ok || address(c).balance == 0);
    }
}

