pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(uint256 seed, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));

        // Move far into the future: blockhash of blocks > 256 back reads as 0.
        vm.roll(1000 + (seed % 100));

        // Player locks a guess. guesses[actor].block = current + 1.
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(bytes32(seed));

        // Roll far beyond the 256-block window so blockhash(guessBlock) == 0,
        // making the winning answer keccak256(abi.encodePacked(bytes32(0))).
        vm.roll(block.number + 300);

        vm.prank(actor);
        c.settle();

        // General rule: a winning settle() pays the full 2-ether pot, so the
        // contract balance is always 0 afterward. The mutant pays only 1 ether,
        // leaving 1 ether stuck (balance == 1 ether), violating the rule.
        assertTrue(address(c).balance == 0);
    }
}

