pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 guess) public {
        vm.assume(actor != address(0) && actor != address(c));

        // lock in the fuzzed guess
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // move just past the target block so settle is callable
        uint256 target = block.number + 1;
        vm.roll(target + 1);

        // settle must succeed whenever the guess is wrong (no payout, no revert)
        bool ok;
        vm.prank(actor);
        try c.settle() { ok = true; } catch { ok = false; }

        // General rule: settling an incorrect guess completes normally.
        // Reference: correct (wrong guess -> no transfer). Mutant: pays 2 ether
        // on a wrong guess from a 1-ether-funded contract -> reverts -> ok == false.
        assertTrue(ok);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 h, uint amt) public {
        require(address(this).balance >= amt);
        uint balBefore = address(c).balance;
        c.lockInGuess{value: amt}(h);
        c.settle();
        c.settle();
        assert(address(c).balance >= balBefore);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        require(true);
        // address(this) has never called lockInGuess on c, so its guess slot
        // is empty: in the original contract settle() always reverts here.
        bool reverted;
        try c.settle() { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 hash, uint amount) public payable {
        require(amount == 1 ether && address(this).balance >= amount);
        c.lockInGuess{value: amount}(hash);
        bool reverted1;
        try c.settle() { reverted1 = false; } catch { reverted1 = true; }
        bool reverted2;
        try c.settle() { reverted2 = false; } catch { reverted2 = true; }
        assert(reverted2);
    }

    receive() external payable {}
}
